const products=$input.all().map(({json})=>({product_id:Number(json.product_id),offer_id:String(json.offer_id)}));
if(!products.length||new Set(products.map(x=>x.product_id)).size!==products.length) throw new Error('Canonical product contract invalid');
return [{json:{products,request_body:{filter:{product_id:products.map(x=>String(x.product_id)),visibility:'ALL'},limit:1000}}}];

const request=$items('Build Price Request')[0].json;
const items=$json.items;
if(!Array.isArray(items)) throw new Error('Price API returned no items');
const expected=new Map(request.products.map(x=>[x.product_id,x.offer_id]));
if(items.length!==expected.size) throw new Error(`Expected ${expected.size} price items, got ${items.length}`);
for(const item of items){if(expected.get(Number(item.product_id))!==String(item.offer_id)) throw new Error('Price attribution contract mismatch');}
const now=new Date(); const slotHour=Math.floor(now.getUTCHours()/6)*6; now.setUTCHours(slotHour,0,0,0);
return [{json:{collection_ref:`ozon-prices-6h-${now.toISOString()}`,collected_at:new Date().toISOString(),items,persist:true}}];
